/**
 * SpectatorCamera - Camera for spectating any physics body
 *
 * Attaches to kinematic or dynamic bodies and provides multiple view modes:
 * - native: Use the body's camera if available, else first-person
 * - firstPerson: First-person view from body's position/rotation
 * - rts: Overhead RTS-style view centered on the body
 * - free: Detached camera (no automatic positioning)
 *
 * Designed for spectating AI agents, multiplayer scenarios, and debugging.
 *
 * @class SpectatorCamera
 * @extends PhysicsCamera
 * @short Camera for spectating any physics body
 * @category Camera
 * @tags Physics, Camera, Spectator, WebGPU, WebGL
 *
 * @example
 * import { SpectatorCamera } from '@three-blocks/pro';
 *
 * const spectator = new SpectatorCamera(physics, {
 *   eyeHeight: 1.7,
 * });
 *
 * // Attach to a bot
 * spectator.attach(bot.body);
 *
 * // Override with RTS style
 * spectator.setMode('rts', { distance: 30, tilt: Math.PI / 3 });
 *
 * // Return to body's native view
 * spectator.setMode('native');
 *
 * // Detach (returns to free camera)
 * spectator.detach();
 *
 * // In animation loop
 * spectator.update(delta);
 * renderer.render(scene, spectator);
 */
export class SpectatorCamera extends PhysicsCamera {
    /**
     * Create a SpectatorCamera.
     *
     * @param {Object} physics - Physics instance
     * @param {Object} [options={}] - Camera options
     * @param {number} [options.eyeHeight=1.7] - Eye height offset for first-person mode
     * @param {number} [options.fov=70] - Field of view
     * @param {number} [options.near=0.1] - Near clipping plane
     * @param {number} [options.far=1000] - Far clipping plane
     */
    constructor(physics: any, options?: {
        eyeHeight?: number;
        fov?: number;
        near?: number;
        far?: number;
    });
    /**
     * Currently attached body (KinematicBody or DynamicBody).
     * @type {Object|null}
     * @private
     */
    private _attachedBody;
    /**
     * Eye height offset for first-person mode.
     * @type {number}
     */
    eyeHeight: number;
    /**
     * Current view mode.
     * @type {'native'|'firstPerson'|'rts'|'free'}
     * @private
     */
    private _mode;
    /**
     * Mode-specific configuration.
     * @type {Object}
     * @private
     */
    private _modeConfig;
    /**
     * Temporary position vector for interpolation.
     * @type {THREE.Vector3}
     * @private
     */
    private _tempPosition;
    /**
     * Temporary quaternion for interpolation.
     * @type {THREE.Quaternion}
     * @private
     */
    private _tempQuat;
    /**
     * Attach to a physics body.
     *
     * @param {Object} body - KinematicBody or DynamicBody to spectate
     * @returns {SpectatorCamera} This instance for chaining
     */
    attach(body: any): SpectatorCamera;
    /**
     * Detach from current body.
     *
     * @returns {SpectatorCamera} This instance for chaining
     */
    detach(): SpectatorCamera;
    /**
     * Set spectator view mode.
     *
     * @param {'native'|'firstPerson'|'rts'|'free'} mode - View mode
     * @param {Object} [config={}] - Mode-specific configuration
     * @param {number} [config.distance=30] - Distance from body (RTS mode)
     * @param {number} [config.tilt=Math.PI/3] - Camera tilt angle (RTS mode)
     * @returns {SpectatorCamera} This instance for chaining
     */
    setMode(mode: "native" | "firstPerson" | "rts" | "free", config?: {
        distance?: number;
        tilt?: number;
    }): SpectatorCamera;
    /**
     * Get currently attached body.
     *
     * @returns {Object|null} KinematicBody, DynamicBody, or null
     */
    get attachedBody(): any | null;
    /**
     * Get current view mode.
     *
     * @returns {'native'|'firstPerson'|'rts'|'free'} Current mode
     */
    get mode(): "native" | "firstPerson" | "rts" | "free";
    /**
     * Check if camera is attached to a body.
     *
     * @returns {boolean} True if attached
     */
    get isAttached(): boolean;
    /**
     * Apply first-person view from body's position.
     * @private
     */
    private _applyFirstPersonView;
    /**
     * Apply RTS-style overhead view.
     * @private
     */
    private _applyRTSView;
    /**
     * Sync camera position/quaternion to sharedCamera buffer.
     * This ensures the worker has correct camera state for rayshoot etc.
     * Sets both prev and current to the same value to prevent interpolation issues.
     * @private
     */
    private _syncToSharedCamera;
}
import { PhysicsCamera } from './PhysicsCamera.js';
